import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Objects;

/**
 * Automatic checks for Java Assignment 1.
 *
 * Do NOT edit this file - your instructor grades with an original copy,
 * so changing it will not change your grade.
 *
 * Run from the repository's main folder:
 *     javac -d out assignment/*.java checker/*.java
 *     java -cp out Checker
 */
public class Checker {

    interface Check {
        void run() throws Exception;
    }

    private static final List<String[]> results = new ArrayList<>();

    public static void main(String[] args) throws IOException {
        Locale.setDefault(Locale.US);   // so %.2f always prints 65.00, never 65,00

        // ---------- Part A ----------
        check("A1", "celsiusToFahrenheit", () -> {
            close(PartA.celsiusToFahrenheit(0), 32, "0 C should be 32 F");
            close(PartA.celsiusToFahrenheit(100), 212, "100 C should be 212 F");
            close(PartA.celsiusToFahrenheit(-40), -40, "-40 C should be -40 F");
            close(PartA.celsiusToFahrenheit(37), 98.6, "37 C should be 98.6 F");
        });
        check("A2", "formatDuration", () -> {
            same(PartA.formatDuration(125), "2 min 5 s", "125 seconds");
            same(PartA.formatDuration(60), "1 min 0 s", "60 seconds");
            same(PartA.formatDuration(59), "0 min 59 s", "59 seconds");
            same(PartA.formatDuration(0), "0 min 0 s", "0 seconds");
        });
        check("A3", "averageOfThree", () -> {
            close(PartA.averageOfThree(70, 80, 95), 245 / 3.0, "Use a double so decimals are kept");
            close(PartA.averageOfThree(1, 2, 2), 5 / 3.0, "Integer division drops the decimals - divide by 3.0");
            close(PartA.averageOfThree(10, 20, 30), 20, "average of 10, 20, 30");
        });
        check("A4", "priceWithVat", () -> {
            close(PartA.priceWithVat(100), 116.0, "100 + 16% VAT");
            close(PartA.priceWithVat(65), 75.4, "65 + 16% VAT");
            close(PartA.priceWithVat(99.99), 115.99, "Round to 2 decimal places");
            close(PartA.priceWithVat(0), 0, "0 stays 0");
        });
        check("A5", "canVote", () -> {
            same(PartA.canVote(21, true), true, "21 with an ID can vote");
            same(PartA.canVote(18, true), true, "18 is old enough (use >=)");
            same(PartA.canVote(17, true), false, "17 is too young");
            same(PartA.canVote(30, false), false, "No ID means no vote (use &&)");
        });

        // ---------- Part B ----------
        check("B1", "initials", () -> {
            same(PartB.initials("amina", "wanjiru"), "A.W.", "Uppercase first letters with dots");
            same(PartB.initials("  brian ", "Otieno"), "B.O.", "trim() the names first");
            same(PartB.initials("Chen", "li"), "C.L.", "initials of Chen Li");
        });
        check("B2", "shout", () -> {
            same(PartB.shout("  hello there "), "HELLO THERE!", "trim, uppercase, add !");
            same(PartB.shout("java"), "JAVA!", "shout(\"java\")");
        });
        check("B3", "maskPhone", () -> {
            same(PartB.maskPhone("0712345678"), "******5678", "Keep only the last 4 digits");
            same(PartB.maskPhone("254712345678"), "********5678", "Works for any length");
            same(PartB.maskPhone("1234"), "1234", "Exactly 4 digits: nothing to hide");
        });
        check("B4", "addNumbers", () -> {
            same(PartB.addNumbers("21", "4"), 25, "21 + 4");
            same(PartB.addNumbers(" 7 ", "-10"), -3, "trim() before Integer.parseInt");
            same(PartB.addNumbers("0", "0"), 0, "0 + 0");
            same(PartB.addNumbers("100", "250"), 350, "100 + 250");
        });
        check("B5", "receiptLine", () -> {
            same(PartB.receiptLine("Bread", 3, 65), "3 x Bread @ KES 65.00 = KES 195.00", "Use %.2f for prices");
            same(PartB.receiptLine("Milk", 2, 59.5), "2 x Milk @ KES 59.50 = KES 119.00", "receipt for Milk");
            same(PartB.receiptLine("Eggs", 12, 15), "12 x Eggs @ KES 15.00 = KES 180.00", "receipt for Eggs");
        });

        // ---------- Part C ----------
        check("C1", "lastElement", () -> {
            same(PartC.lastElement(new int[]{4, 8, 15}), 15, "The last index is length - 1");
            same(PartC.lastElement(new int[]{42}), 42, "One-item array");
            same(PartC.lastElement(new int[]{-1, -2, -3}), -3, "Negative numbers");
        });
        check("C2", "sortedCopy", () -> {
            int[] original = {3, 1, 2};
            int[] result = PartC.sortedCopy(original);
            sameArray(result, new int[]{1, 2, 3}, "Sorted ascending");
            sameArray(original, new int[]{3, 1, 2}, "Do not change the original - sort a COPY");
            sameArray(PartC.sortedCopy(new int[]{}), new int[]{}, "Empty array gives an empty array");
        });
        check("C3", "sum", () -> {
            same(PartC.sum(new int[]{72, 55, 89}), 216, "72 + 55 + 89");
            same(PartC.sum(new int[]{}), 0, "Empty array gives 0");
            same(PartC.sum(new int[]{-5, 5, 10}), 10, "Negative numbers count too");
        });
        check("C4", "uniqueCount", () -> {
            same(PartC.uniqueCount(listOf("Nairobi", "Mombasa", "Nairobi")), 2, "Nairobi counts once");
            same(PartC.uniqueCount(listOf()), 0, "Empty list gives 0");
            same(PartC.uniqueCount(listOf("a", "b", "c", "a", "b", "a")), 3, "three different letters");
        });
        check("C5", "wordCount", () -> {
            HashMap<String, Integer> expected = new HashMap<>();
            expected.put("the", 2);
            expected.put("cat", 1);
            expected.put("and", 1);
            expected.put("hat", 1);
            same(PartC.wordCount("the cat and the hat"), expected, "Count each word");
            HashMap<String, Integer> go = new HashMap<>();
            go.put("go", 3);
            same(PartC.wordCount("Go go GO"), go, "Count words in lowercase");
        });

        report();
    }

    // ---------------- helpers ----------------

    private static void check(String id, String name, Check c) {
        try {
            c.run();
            results.add(new String[]{id, name, "PASS", ""});
        } catch (AssertionError e) {
            results.add(new String[]{id, name, "FAIL", e.getMessage()});
        } catch (Throwable t) {
            results.add(new String[]{id, name, "FAIL",
                    "crashed with " + t.getClass().getSimpleName()
                            + (t.getMessage() == null ? "" : ": " + t.getMessage())});
        }
    }

    private static void same(Object actual, Object expected, String hint) {
        if (!Objects.equals(actual, expected)) {
            throw new AssertionError(hint + " - expected " + show(expected) + " but got " + show(actual));
        }
    }

    private static void close(double actual, double expected, String hint) {
        if (Math.abs(actual - expected) > 1e-6) {
            throw new AssertionError(hint + " - expected " + expected + " but got " + actual);
        }
    }

    private static void sameArray(int[] actual, int[] expected, String hint) {
        if (!Arrays.equals(actual, expected)) {
            throw new AssertionError(hint + " - expected " + Arrays.toString(expected)
                    + " but got " + Arrays.toString(actual));
        }
    }

    private static String show(Object value) {
        return value instanceof String ? "\"" + value + "\"" : String.valueOf(value);
    }

    private static ArrayList<String> listOf(String... items) {
        return new ArrayList<>(Arrays.asList(items));
    }

    private static void report() throws IOException {
        int passed = 0;
        StringBuilder table = new StringBuilder();
        StringBuilder csv = new StringBuilder("exercise,result\n");
        for (String[] r : results) {
            boolean ok = r[2].equals("PASS");
            if (ok) {
                passed++;
            }
            System.out.printf("%s %-20s %s%n", r[0], r[1], ok ? "PASS" : "FAIL  " + r[3]);
            table.append("| ").append(r[0]).append(" ").append(r[1]).append(" | ")
                 .append(ok ? "✅ pass" : "❌ fail").append(" | ")
                 .append(r[3].replace("|", "\\|")).append(" |\n");
            csv.append(r[0]).append(",").append(ok ? 1 : 0).append("\n");
        }
        String score = "Score: " + passed + "/" + results.size();
        System.out.println("\n" + score);

        try (FileWriter out = new FileWriter("results.csv")) {
            out.write(csv.toString());
        }

        String summaryFile = System.getenv("GITHUB_STEP_SUMMARY");
        if (summaryFile != null) {
            try (FileWriter out = new FileWriter(summaryFile, true)) {
                out.write("## " + score + "\n\n| Exercise | Result | Hint |\n| --- | --- | --- |\n" + table);
            }
        }

        if (passed < results.size()) {
            System.exit(1);
        }
    }
}
